246	/** Loads sheets by id; a sheet never loaded before is started empty, its today the real date. */
247	@Service
248	public class SheetService {
249	
250	    private final SheetRepository sheets;
251	    private final Rollup rollup;
252	    private final Audit audit;
253	
254	    public SheetService(SheetRepository sheets, Rollup rollup, Audit audit) {
255	        this.sheets = sheets;
256	        this.rollup = rollup;
257	        this.audit = audit;
258	    }
259	
260	    @Transactional
261	    public Sheet load(String id, String user) {
262	        return sheets.findById(id).orElseGet(() -> {
263	            try {
264	                return sheets.saveAndFlush(new Sheet(id, user, Instant.now(), LocalDate.now()));
265	            } catch (DataIntegrityViolationException e) {
266	                // Another user started the same sheet at the same moment.
267	                return sheets.findById(id).orElseThrow(() -> e);
268	            }
269	        });
270	    }
271	
272	    /** The sheet's today. Every date decision and default date in the sheet goes through this. */
273	    @Transactional(readOnly = true)
274	    public LocalDate today(String id) {
275	        return sheets.findById(id).map(Sheet::getToday).orElseThrow(SheetNotFoundException::new);
276	    }
277	
278	    /** Change the sheet's today, recording the figures it moves. */
279	    @Transactional
280	    public Sheet setToday(String id, String user, LocalDate today) {
281	        Sheet sheet = sheets.findById(id).orElseThrow(SheetNotFoundException::new);
282	        Rollup.Snapshot before = rollup.take(id);
283	        sheet.setToday(today);
284	        rollup.recordChanges(id, user, before);
285	        return sheet;
286	    }
287	
288	    /** Change the sheet's clerk limit: the largest due a clerk may settle; none for no limit. */
289	    @Transactional
290	    public Sheet setClerkLimit(String id, String user, BigDecimal limit) {
291	        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
292	        sheet.setClerkLimit(limit == null ? null : limit.setScale(2));
293	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=clerk-limit value="
294	                + (sheet.getClerkLimit() == null ? "" : sheet.getClerkLimit().toPlainString()));
295	        return sheet;
296	    }
297	
298	    /** Change the sheet's floor: the least a claim's live due can be, recording the figures it moves. */
299	    @Transactional
300	    public Sheet setFloor(String id, String user, BigDecimal floor) {
301	        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
302	        Rollup.Snapshot before = rollup.take(id);
303	        sheet.setFloor(floor.setScale(2));
304	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=floor value="
305	                + sheet.getFloor().toPlainString());
306	        rollup.recordChanges(id, user, before);
307	        return sheet;
308	    }
309	
310	    /** Change the sheet's terms: the number of days after a claim's date it is due by. */
311	    @Transactional
312	    public Sheet setTerms(String id, String user, int terms) {
313	        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
314	        sheet.setTerms(terms);
315	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=terms value=" + terms);
316	        return sheet;
317	    }
318	
319	    /** The sheet's next claim number: 1 for the first, then 2, and so on, never given twice. */
320	    @Transactional
321	    public int nextClaimNumber(String id) {
322	        return sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new).nextClaimNumber();
323	    }
324	}
