350	/**
351	 * Each person's claimed and due-total on a sheet, and the sheet's totals, as the screen shows them.
352	 * A change takes the figures before it, then records after its own audit lines a ROLLUP line for each
353	 * person whose figures moved (a person new to the sheet counting as moved), in the order they were
354	 * added, and a TOTALS line when the sheet's totals moved.
355	 */
356	@Service
357	public class Rollup {
358	
359	    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2);
360	
361	    /** A person's figures; a null due-total is n/a. */
362	    public record Figures(String name, BigDecimal claimed, BigDecimal dueTotal) {
363	    }
364	
365	    /** Everyone's figures by person id, in the order they were added, and the sheet's totals. */
366	    public record Snapshot(Map<Long, Figures> people, BigDecimal claimedTotal, BigDecimal dueTotal) {
367	    }
368	
369	    private final PersonRepository people;
370	    private final ClaimRepository claims;
371	    private final RateRepository rates;
372	    private final SheetRepository sheets;
373	    private final Audit audit;
374	
375	    public Rollup(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
376	            Audit audit) {
377	        this.people = people;
378	        this.claims = claims;
379	        this.rates = rates;
380	        this.sheets = sheets;
381	        this.audit = audit;
382	    }
383	
384	    /** The sheet's figures now. */
385	    public Snapshot take(String sheetId) {
386	        Optional<Sheet> sheet = sheets.findById(sheetId);
387	        LocalDate today = sheet.map(Sheet::getToday).orElse(null);
388	        List<Rate> sheetRates = rates.findBySheetIdOrderByGradeAsc(sheetId);
389	        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
390	        Map<Long, Figures> figures = new LinkedHashMap<>();
391	        BigDecimal claimedTotal = ZERO;
392	        BigDecimal dueTotal = ZERO;
393	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
394	            BigDecimal claimed = ZERO;
395	            BigDecimal due = ZERO;
396	            boolean keptFigure = false;
397	            for (Claim claim : sheetClaims) {
398	                if (!claim.getPersonId().equals(person.getId()) || !countsLive(claim, person.isHeld())) {
399	                    continue;
400	                }
401	                claimed = claimed.add(claim.getAmount());
402	                BigDecimal kept = claim.getSettledDue() != null ? claim.getSettledDue()
403	                        : claim.isStated() ? claim.getStatedDue() : null;
404	                if (kept != null) {
405	                    keptFigure = true;
406	                    due = due.add(kept);
407	                } else if (!claim.isStated()) {
408	                    BigDecimal live = inForce(sheetRates, person.getGrade(), claim.getDate())
409	                            .map(rate -> claim.getAmount().multiply(rate.getRate()).movePointLeft(2)
410	                                    .setScale(2, RoundingMode.HALF_EVEN))
411	                            .map(d -> sheet.map(s -> s.floored(d)).orElse(d))
412	                            .orElse(ZERO);
413	                    due = due.add(live);
414	                }
415	            }
416	            boolean rated = today != null && inForce(sheetRates, person.getGrade(), today).isPresent();
417	            BigDecimal personDue = rated || keptFigure ? due : null;
418	            figures.put(person.getId(), new Figures(person.getName(), claimed, personDue));
419	            claimedTotal = claimedTotal.add(claimed);
420	            if (personDue != null) {
421	                dueTotal = dueTotal.add(personDue);
422	            }
423	        }
424	        return new Snapshot(figures, claimedTotal, dueTotal);
425	    }
426	
427	    /** The due-total of the claims that count dated from one date to another, both inclusive, as the
428	     *  screen shows a period's: each claim's settled due, else the figure its statement bound, else its
429	     *  live due, at least the floor (a claim with no figure adds nothing). */
430	    public BigDecimal dueBetween(String sheetId, LocalDate from, LocalDate to) {
431	        Optional<Sheet> sheet = sheets.findById(sheetId);
432	        List<Rate> sheetRates = rates.findBySheetIdOrderByGradeAsc(sheetId);
433	        Map<Long, String> grades = new LinkedHashMap<>();
434	        Set<Long> held = new HashSet<>();
435	        people.findBySheetIdOrderByIdAsc(sheetId).forEach(p -> {
436	            grades.put(p.getId(), p.getGrade());
437	            if (p.isHeld()) {
438	                held.add(p.getId());
439	            }
440	        });
441	        BigDecimal total = ZERO;
442	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
443	            if (!countsLive(claim, held.contains(claim.getPersonId())) || claim.getDate().isBefore(from) || claim.getDate().isAfter(to)) {
444	                continue;
445	            }
446	            BigDecimal due;
447	            if (claim.getSettledDue() != null) {
448	                due = claim.getSettledDue();
449	            } else if (claim.isStated()) {
450	                due = claim.getStatedDue();
451	            } else {
452	                String grade = grades.get(claim.getPersonId());
453	                due = grade == null ? null : inForce(sheetRates, grade, claim.getDate())
454	                        .map(rate -> claim.getAmount().multiply(rate.getRate()).movePointLeft(2)
455	                                .setScale(2, RoundingMode.HALF_EVEN))
456	                        .map(d -> sheet.map(s -> s.floored(d)).orElse(d))
457	                        .orElse(null);
458	            }
459	            if (due != null) {
460	                total = total.add(due);
461	            }
462	        }
463	        return total;
464	    }
465	
466	    /** Record, once the change commits, the lines for every figure that moved since {@code before}. */
467	    public void recordChanges(String sheetId, String user, Snapshot before) {
468	        Snapshot after = take(sheetId);
469	        String prefix = " sheet=" + sheetId + " by=" + user;
470	        after.people().forEach((id, now) -> {
471	            Figures was = before.people().get(id);
472	            if (was == null || was.claimed().compareTo(now.claimed()) != 0
473	                    || !sameDue(was.dueTotal(), now.dueTotal())) {
474	                audit.recordOnCommit("ROLLUP" + prefix + " person=" + now.name()
475	                        + " claimed=" + now.claimed().toPlainString() + " due-total=" + show(now.dueTotal()));
476	            }
477	        });
478	        if (before.claimedTotal().compareTo(after.claimedTotal()) != 0
479	                || before.dueTotal().compareTo(after.dueTotal()) != 0) {
480	            audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + after.claimedTotal().toPlainString()
481	                    + " due-total=" + after.dueTotal().toPlainString());
482	        }
483	    }
484	
485	    /** Whether a claim counts in the live totals: its status counts, and it is not OPEN while its
486	     *  person is on hold. */
487	    private static boolean countsLive(Claim claim, boolean held) {
488	        return claim.getStatus().counts() && !(held && claim.getStatus() == ClaimStatus.OPEN);
489	    }
490	
491	    private static boolean sameDue(BigDecimal a, BigDecimal b) {
492	        return a == null || b == null ? Objects.equals(a, b) : a.compareTo(b) == 0;
493	    }
494	
495	    private static String show(BigDecimal due) {
496	        return due == null ? "n/a" : due.toPlainString();
497	    }
498	
499	    /** The grade's rate in force on a date: the latest from-date on or before it, none first. */
500	    private static Optional<Rate> inForce(List<Rate> sheetRates, String grade, LocalDate date) {
501	        return sheetRates.stream()
502	                .filter(r -> r.getGrade().equals(grade))
503	                .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(date))
504	                .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())));
505	    }
506	}
