726	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note) {
727	        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
728	        LocalDate on = date != null ? date : sheets.today(sheetId);
729	        refuseClosed(sheetId, on);
730	        refuseRetired(person, on);
731	        Rollup.Snapshot before = rollup.take(sheetId);
732	        Claim claim = claims.saveAndFlush(new Claim(sheetId, personId, amount.setScale(2), on, note));
733	        audit("CLAIM_ADDED", claim, person, user);
734	        rollup.recordChanges(sheetId, user, before);
735	        return claim;
736	    }
737	
738	    /** Change a DRAFT claim; a claim in any other status is refused. */
739	    @Transactional
740	    public Claim update(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note) {
741	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
742	        if (claim.getStatus() != ClaimStatus.DRAFT) {
743	            throw new ClaimNotDraftException(claim.getStatus());
744	        }
745	        LocalDate on = date != null ? date : sheets.today(sheetId);
746	        refuseClosed(sheetId, claim.getDate());
747	        refuseClosed(sheetId, on);
748	        refuseRetired(people.findByIdAndSheetId(claim.getPersonId(), sheetId)
749	                .orElseThrow(PersonNotFoundException::new), on);
750	        Rollup.Snapshot before = rollup.take(sheetId);
751	        claim.setAmount(amount.setScale(2));
752	        claim.setDate(on);
753	        claim.setNote(note);
754	        Claim updated = claims.saveAndFlush(claim);
755	        Person person = people.findByIdAndSheetId(updated.getPersonId(), sheetId)
756	                .orElseThrow(PersonNotFoundException::new);
757	        audit("CLAIM_EDITED", updated, person, user);
758	        rollup.recordChanges(sheetId, user, before);
759	        return updated;
760	    }
761	
762	    /** Move a claim to another status; refused when its current status does not allow it,
763	     *  or when the user settling it is the one who opened it, or is a clerk and its due is above the
764	     *  sheet's clerk limit (a due of n/a is within any limit). Settling fixes the
765	     *  claim's due at its grade's rate in force on its date (a claim bound by a statement at the figure it
766	     *  bound); with no figure then, its due stays live. */
767	    @Transactional
768	    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus to) {
769	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
770	        refuseClosed(sheetId, claim.getDate());
771	        if (!claim.getStatus().canBecome(to)) {
772	            throw new ClaimStatusException(claim.getStatus(), to);
773	        }
774	        if (to == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
775	            throw new ClaimSettlerException();
776	        }
777	        Rollup.Snapshot before = rollup.take(sheetId);
778	        Integer number = claim.getNumber();
779	        if (to == ClaimStatus.OPEN) {
780	            number = sheets.nextClaimNumber(sheetId);
781	            claim.setOpenedBy(user);
782	        }
783	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
784	                .orElseThrow(PersonNotFoundException::new);
785	        if (to == ClaimStatus.SETTLED) {
786	            BigDecimal due = claim.isStated() ? claim.getStatedDue() : liveDue(claim, person);
787	            refuseOverLimit(sheetId, user, due);
788	            claim.setSettledDue(due);
789	        }
790	        claim.setStatus(to);
791	        claim.setNumber(number);
792	        Claim updated = claims.saveAndFlush(claim);
793	        String event = switch (to) {
794	            case OPEN -> "CLAIM_OPENED";
795	            case SETTLED -> "CLAIM_SETTLED";
796	            case VOID -> "CLAIM_VOIDED";
797	            case DRAFT -> throw new IllegalStateException();
798	        };
799	        audit(event, updated, person, user, number, to == ClaimStatus.SETTLED
800	                ? " due=" + (updated.getSettledDue() == null ? "n/a" : updated.getSettledDue().toPlainString())
801	                : "");
802	        rollup.recordChanges(sheetId, user, before);
803	        return updated;
804	    }
805	
806	    /** A person, their statements in the order taken, and their claims newest first. */
807	    public record Stated(Person person, List<Statement> statements, List<Claim> claims) {
808	    }
809	
810	    /** Take a person's statement: record their due-total now and how many claims count, and bind each
811	     *  claim that counts to the figure it has now; a claim that does not count is left unbound. */
812	    @Transactional
813	    public Stated statement(String sheetId, String user, long personId) {
814	        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
815	        LocalDate today = sheets.today(sheetId);
816	        List<Claim> theirs = claims.findForUpdateBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
817	        Rollup.Snapshot before = rollup.take(sheetId);
818	        BigDecimal total = BigDecimal.ZERO.setScale(2);
819	        boolean figure = false;
820	        int counted = 0;
821	        for (Claim claim : theirs) {
822	            if (!claim.getStatus().counts()) {
823	                claim.setStated(false, null);
824	                continue;
825	            }
826	            BigDecimal due = due(claim, person);
827	            if (due != null) {
828	                total = total.add(due);
829	                figure |= claim.getSettledDue() != null || claim.isStated();
830	            }
831	            claim.setStated(true, due);
832	            counted++;
833	        }
834	        boolean rated = rates.findInForce(sheetId, person.getGrade(), today).isPresent();
835	        BigDecimal dueTotal = rated || figure ? total : null;
836	        claims.saveAllAndFlush(theirs);
837	        statements.saveAndFlush(new Statement(sheetId, personId, today, dueTotal, counted));
838	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
839	                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + counted);
840	        rollup.recordChanges(sheetId, user, before);
841	        return new Stated(person, statements.findByPersonIdOrderByIdAsc(personId), theirs);
842	    }
843	
844	    /** Refuse a change to a claim dated inside a closed period. Locks the sheet first, so a period being
845	     *  closed at the same moment is seen. */
846	    private void refuseClosed(String sheetId, LocalDate date) {
847	        sheetRows.findForUpdateById(sheetId).orElseThrow(SheetNotFoundException::new);
848	        if (periods.closedOn(sheetId, date)) {
849	            throw new PeriodClosedException();
850	        }
851	    }
852	
853	    /** Refuse a clerk settling a due above the sheet's clerk limit; a steward settles anything, and a due
854	     *  of n/a, or a sheet with no limit, is within it. */
855	    private void refuseOverLimit(String sheetId, String user, BigDecimal due) {
856	        BigDecimal limit = sheetRows.findById(sheetId).orElseThrow(SheetNotFoundException::new).getClerkLimit();
857	        if (limit != null && due != null && due.compareTo(limit) > 0 && !roles.isSteward(sheetId, user)) {
858	            throw new ClaimLimitException();
859	        }
860	    }
861	
862	    /** Refuse a claim dated after its person's retirement date. */
863	    private static void refuseRetired(Person person, LocalDate date) {
864	        if (person.retiredOn(date)) {
865	            throw new PersonRetiredException();
866	        }
867	    }
868	
869	    /** A claim's figure: the due fixed when settled, else the one its last statement bound, else its live
870	     *  due; none when that is n/a. */
871	    private BigDecimal due(Claim claim, Person person) {
872	        if (claim.getSettledDue() != null) {
873	            return claim.getSettledDue();
874	        }
875	        return claim.isStated() ? claim.getStatedDue() : liveDue(claim, person);
876	    }
877	
878	    /** The claim's amount at its person's grade's rate in force on its date, at least the sheet's floor;
879	     *  none when no rate applies. */
880	    private BigDecimal liveDue(Claim claim, Person person) {
881	        Sheet sheet = sheetRows.findById(claim.getSheetId()).orElseThrow(SheetNotFoundException::new);
882	        return rates.findInForce(claim.getSheetId(), person.getGrade(), claim.getDate())
883	                .map(rate -> sheet.floored(due(claim.getAmount(), rate)))
884	                .orElse(null);
885	    }
886	
887	    /** An amount times a rate, divided by 100, rounded half to even to cents. */
888	    private static BigDecimal due(BigDecimal amount, Rate rate) {
889	        return amount.multiply(rate.getRate()).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN);
890	    }
891	
892	    /** The amount as the screen shows it (two decimals), the date YYYY-MM-DD. */
893	    private void audit(String event, Claim claim, Person person, String user) {
894	        audit(event, claim, person, user, claim.getNumber(), "");
895	    }
896	
897	    /** A claim with a number (a voided claim keeps its own) follows its date with number=, then any extra fields. */
898	    private void audit(String event, Claim claim, Person person, String user, Integer number, String extra) {
899	        audit.recordOnCommit(event + " sheet=" + claim.getSheetId() + " by=" + user
900	                + " person=" + person.getName() + " amount=" + claim.getAmount().toPlainString()
901	                + " date=" + claim.getDate() + (number != null ? " number=" + number : "") + extra);
902	    }
903	}
