import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, computed, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { People, Person } from './people';
import { Session, addDays, isDate } from './session';

export interface Claim {
  id: number;
  personId: number;
  /** Two decimals, as the server stores it. */
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  /** Given when opened, the next on the sheet; null while a draft or once voided. */
  number: number | null;
  /** The due fixed when it was settled, two decimals; null while its due is live (not settled, or
   *  settled while its grade had no rate). */
  settledDue: string | null;
  /** The user who opened it; null while a draft. That user cannot settle it. */
  openedBy: string | null;
  /** Bound by its person's last statement, which counted it: it shows and totals `statedDue`. */
  stated: boolean;
  /** The figure the last statement bound, two decimals; null while unbound, or when that was n/a. */
  statedDue: string | null;
}

/** DRAFT when added; DRAFT -> OPEN -> SETTLED, and DRAFT or OPEN -> VOID. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';

/** A status change a claim's buttons ask for. */
export type ClaimAction = 'open' | 'settle' | 'void';

/** Whether a claim in this status counts toward claimed, due-total and every total. */
export function counts(c: Claim): boolean {
  return c.status === 'OPEN' || c.status === 'SETTLED';
}

export interface ClaimFields {
  amount: string;
  /** Blank takes the sheet's today. */
  date: string;
  note: string;
}

// The people's claims on the active sheet, newest first, re-read from the server each time the
// sheet is loaded. Sums are kept in whole cents so they add up exactly, and count only OPEN and
// SETTLED claims.
@Injectable({ providedIn: 'root' })
export class Claims {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);
  private readonly people = inject(People);

  readonly claims = signal<Claim[]>([]);
  private loads = 0;

  /** The claims that count in the live totals: those that count, less the OPEN claims of a person
   *  on hold. */
  readonly live = computed(() => {
    const held = new Set(this.people.people().filter((p) => p.held).map((p) => p.id));
    return this.claims().filter((c) => counts(c) && !(c.status === 'OPEN' && held.has(c.personId)));
  });

  /** Each person's claimed, in cents, by person id. */
  readonly claimedCents = computed(() => {
    const out = new Map<number, number>();
    for (const c of this.live()) out.set(c.personId, (out.get(c.personId) ?? 0) + cents(c.amount));
    return out;
  });

  /** Everyone's claimed added up, with two decimals. */
  readonly total = computed(() => money(this.live().reduce((sum, c) => sum + cents(c.amount), 0)));

  /** The date a claim is due by: its date plus the sheet's terms. */
  dueBy(c: Claim): string {
    return addDays(c.date, this.session.terms());
  }

  /** Whether a claim is overdue: OPEN, with its due-by before the sheet's today. */
  overdue(c: Claim): boolean {
    const today = this.session.today();
    return c.status === 'OPEN' && today !== null && this.dueBy(c) < today;
  }

  /** A person's claims, newest first. */
  of(personId: number): Claim[] {
    return this.claims().filter((c) => c.personId === personId);
  }

  /** A person's claimed, with two decimals. */
  claimed(personId: number): string {
    return money(this.claimedCents().get(personId) ?? 0);
  }

  /** Replace a person's claims with these, as the server answered them (newest first). */
  replaceOf(personId: number, theirs: Claim[]): void {
    const byId = new Map(theirs.map((c) => [c.id, c]));
    this.claims.update((cs) => cs.map((c) => (c.personId === personId ? (byId.get(c.id) ?? c) : c)));
  }

  /** Re-read the active sheet's claims from the server; an error message when that failed. */
  async load(): Promise<string | null> {
    const user = this.session.user();
    const sid = this.session.sheetId();
    const load = ++this.loads;
    this.claims.set([]);
    if (!user || !sid) return null;
    try {
      const claims = await firstValueFrom(
        this.http.get<Claim[]>(`${this.url(sid)}/claims`, { headers: { 'X-User': user } }),
      );
      if (load === this.loads) this.claims.set(claims);
      return null;
    } catch (e) {
      return failed('load', e).replace(' claim', ' claims');
    }
  }

  /** Add a claim for a person; an error message when refused. */
  async add(personId: number, f: ClaimFields): Promise<string | null> {
    const refused = this.check(f);
    if (refused) return refused;
    const sid = this.session.sheetId()!;
    try {
      const claim = await firstValueFrom(
        this.http.post<Claim>(`${this.url(sid)}/people/${personId}/claims`, this.body(f), {
          headers: { 'X-User': this.session.user()! },
        }),
      );
      if (this.session.sheetId() === sid) this.claims.update((cs) => [claim, ...cs]);
      return null;
    } catch (e) {
      return failed('add', e);
    }
  }

  /** Quick-add a DRAFT claim dated the sheet's today, with an empty note, for the person with the
   *  name, the server adding them with grade A first when the sheet has no one by it; an error
   *  message when refused. */
  async quickAdd(name: string, amount: string): Promise<string | null> {
    if (!this.session.user() || !this.session.sheetId()) return 'Load a sheet first.';
    if (!name.trim()) return 'Enter a name.';
    const refused = this.check({ amount, date: '', note: '' });
    if (refused) return refused;
    const sid = this.session.sheetId()!;
    try {
      const added = await firstValueFrom(
        this.http.post<{ person: Person; personAdded: boolean; claim: Claim }>(
          `${this.url(sid)}/quick-claims`,
          { name: name.trim(), amount: amount.trim() },
          { headers: { 'X-User': this.session.user()! } },
        ),
      );
      if (this.session.sheetId() === sid) {
        this.people.people.update((ps) =>
          ps.some((p) => p.id === added.person.id)
            ? ps.map((p) => (p.id === added.person.id ? added.person : p))
            : [...ps, added.person],
        );
        this.claims.update((cs) => [added.claim, ...cs]);
      }
      return null;
    } catch (e) {
      return failed('add', e);
    }
  }

  /** Change a DRAFT claim's amount, date and note; when refused, the reason and whether it is the
   *  claim itself that refused it (it is no longer a DRAFT) rather than the fields typed. */
  async update(id: number, f: ClaimFields): Promise<{ message: string; onClaim: boolean } | null> {
    const refused = this.check(f);
    if (refused) return { message: refused, onClaim: false };
    const sid = this.session.sheetId()!;
    try {
      const claim = await firstValueFrom(
        this.http.put<Claim>(`${this.url(sid)}/claims/${id}`, this.body(f), {
          headers: { 'X-User': this.session.user()! },
        }),
      );
      if (this.session.sheetId() === sid) this.claims.update((cs) => cs.map((c) => (c.id === id ? claim : c)));
      return null;
    } catch (e) {
      if (e instanceof HttpErrorResponse && e.status === 409) {
        return { message: message(e) ?? 'Only a DRAFT claim can be edited.', onClaim: true };
      }
      return { message: failed('save', e), onClaim: false };
    }
  }

  /** Open, settle or void a claim; an error message when refused. */
  async act(id: number, action: ClaimAction): Promise<string | null> {
    const sid = this.session.sheetId();
    const user = this.session.user();
    if (!user || !sid) return 'Load a sheet first.';
    try {
      const claim = await firstValueFrom(
        this.http.post<Claim>(`${this.url(sid)}/claims/${id}/${action}`, null, { headers: { 'X-User': user } }),
      );
      if (this.session.sheetId() === sid) this.claims.update((cs) => cs.map((c) => (c.id === id ? claim : c)));
      return null;
    } catch (e) {
      if (e instanceof HttpErrorResponse && e.status === 409) return refusal(e, action);
      return failed(action, e);
    }
  }

  private check(f: ClaimFields): string | null {
    if (!this.session.user() || !this.session.sheetId()) return 'Load a sheet first.';
    if (!/^\d+(\.\d{1,2})?$/.test(f.amount.trim())) return 'Enter an amount of 0.00 or more, with up to two decimals.';
    if (f.date.trim() && !isDate(f.date.trim())) return 'Enter a date as YYYY-MM-DD.';
    return null;
  }

  private body(f: ClaimFields): { amount: string; date: string | null; note: string } {
    return { amount: f.amount.trim(), date: f.date.trim() || null, note: f.note.trim() };
  }

  private url(sid: string): string {
    return `/api/sheets/${encodeURIComponent(sid)}`;
  }
}

/** An amount written with up to two decimals, in whole cents. */
function cents(amount: string): number {
  const [whole, frac = ''] = amount.split('.');
  return Number(whole) * 100 + Number((frac + '00').slice(0, 2));
}

/** Cents as an amount with two decimals. */
function money(cents: number): string {
  return `${Math.floor(cents / 100)}.${String(cents % 100).padStart(2, '0')}`;
}

function refusal(e: HttpErrorResponse, action: ClaimAction): string {
  return message(e) ?? `This claim's status does not allow it to ${action}.`;
}

/** The reason the server gave for a refusal, when it gave one. */
function message(e: HttpErrorResponse): string | null {
  const err: unknown = e.error;
  if (err && typeof err === 'object' && 'message' in err && typeof err.message === 'string' && err.message) {
    return err.message;
  }
  return null;
}

function failed(what: string, e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 409) return message(e) ?? `Could not ${what} claim (409).`;
  if (e instanceof HttpErrorResponse && e.status === 400) return 'Enter an amount of 0.00 or more, with up to two decimals.';
  return e instanceof HttpErrorResponse ? `Could not ${what} claim (${e.status}).` : `Could not ${what} claim.`;
}
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';

export interface SheetView {
  id: string;
  today: string;
  /** The largest due a clerk may settle, two decimals; null when there is no limit. */
  clerkLimit: string | null;
  /** The least a claim's live due can be, two decimals. */
  floor: string;
  /** The number of days after a claim's date it is due by. */
  terms: number;
}

// The signed-in user (a typed name, no password) and the active sheet. Every request to the
// server carries the user's name in the X-User header.
@Injectable({ providedIn: 'root' })
export class Session {
  private readonly http = inject(HttpClient);

  readonly user = signal<string | null>(null);
  readonly sheetId = signal<string | null>(null);
  /** The sheet's today (YYYY-MM-DD): every date decision and default date uses it, never the clock. */
  readonly today = signal<string | null>(null);
  /** The sheet's clerk limit (two decimals); null when there is none. */
  readonly clerkLimit = signal<string | null>(null);
  /** The sheet's floor (two decimals): the least a claim's live due can be. */
  readonly floor = signal<string>('1.00');
  /** The sheet's terms: the number of days after a claim's date it is due by. */
  readonly terms = signal<number>(14);

  signIn(name: string): boolean {
    const n = name.trim();
    if (!n) return false;
    this.user.set(n);
    return true;
  }

  async loadSheet(id: string): Promise<string | null> {
    const user = this.user();
    const sid = id.trim();
    if (!user) return 'Sign in first.';
    if (!sid) return 'Enter a sheet id.';
    try {
      const sheet = await firstValueFrom(
        this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(sid)}/load`, null, {
          headers: { 'X-User': user },
        }),
      );
      this.sheetId.set(sheet.id);
      this.today.set(sheet.today);
      this.clerkLimit.set(sheet.clerkLimit);
      this.floor.set(sheet.floor);
      this.terms.set(sheet.terms);
      return null;
    } catch (e) {
      return e instanceof HttpErrorResponse ? `Could not load sheet (${e.status}).` : 'Could not load sheet.';
    }
  }

  async setToday(date: string): Promise<string | null> {
    const user = this.user();
    const sid = this.sheetId();
    const d = date.trim();
    if (!user || !sid) return 'Load a sheet first.';
    if (!isDate(d)) return 'Enter a date as YYYY-MM-DD.';
    try {
      const sheet = await firstValueFrom(
        this.http.put<SheetView>(`/api/sheets/${encodeURIComponent(sid)}/today`, { today: d }, {
          headers: { 'X-User': user },
        }),
      );
      if (this.sheetId() === sheet.id) this.today.set(sheet.today);
      return null;
    } catch (e) {
      return e instanceof HttpErrorResponse ? `Could not change today (${e.status}).` : 'Could not change today.';
    }
  }

  /** Change the sheet's clerk limit (blank: no limit); an error message when refused. */
  async setClerkLimit(limit: string): Promise<string | null> {
    const user = this.user();
    const sid = this.sheetId();
    const l = limit.trim();
    if (!user || !sid) return 'Load a sheet first.';
    if (l && !/^\d+(\.\d{1,2})?$/.test(l)) return 'Enter a clerk limit of 0.00 or more, with up to two decimals, or leave it blank.';
    try {
      const sheet = await firstValueFrom(
        this.http.put<SheetView>(`/api/sheets/${encodeURIComponent(sid)}/settings`, { clerkLimit: l || null }, {
          headers: { 'X-User': user },
        }),
      );
      if (this.sheetId() === sheet.id) this.clerkLimit.set(sheet.clerkLimit);
      return null;
    } catch (e) {
      return e instanceof HttpErrorResponse ? `Could not save settings (${e.status}).` : 'Could not save settings.';
    }
  }

  /** Change the sheet's floor; an error message when refused. */
  async setFloor(floor: string): Promise<string | null> {
    const user = this.user();
    const sid = this.sheetId();
    const f = floor.trim();
    if (!user || !sid) return 'Load a sheet first.';
    if (!/^\d+(\.\d{1,2})?$/.test(f)) return 'Enter a floor of 0.00 or more, with up to two decimals.';
    try {
      const sheet = await firstValueFrom(
        this.http.put<SheetView>(`/api/sheets/${encodeURIComponent(sid)}/settings/floor`, { floor: f }, {
          headers: { 'X-User': user },
        }),
      );
      if (this.sheetId() === sheet.id) this.floor.set(sheet.floor);
      return null;
    } catch (e) {
      return e instanceof HttpErrorResponse ? `Could not save settings (${e.status}).` : 'Could not save settings.';
    }
  }

  /** Change the sheet's terms (whole days); an error message when refused. */
  async setTerms(terms: string): Promise<string | null> {
    const user = this.user();
    const sid = this.sheetId();
    const t = terms.trim();
    if (!user || !sid) return 'Load a sheet first.';
    if (!/^\d{1,5}$/.test(t) || Number(t) > 36500) return 'Enter terms as a whole number of days, 0 or more.';
