394	/** A date (YYYY-MM-DD) moved on a number of days, worked out on the calendar without the clock. */
395	export function addDays(date: string, days: number): string {
396	  const [y, m, d] = date.split('-').map(Number);
397	  return fromDayNumber(dayNumber(y, m, d) + days);
398	}
399	
400	/** Days since 1970-01-01 of a calendar date. */
401	function dayNumber(y: number, m: number, d: number): number {
402	  const yy = m <= 2 ? y - 1 : y;
403	  const era = Math.floor(yy / 400);
404	  const yoe = yy - era * 400;
405	  const doy = Math.floor((153 * (m + (m > 2 ? -3 : 9)) + 2) / 5) + d - 1;
406	  const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
407	  return era * 146097 + doe - 719468;
408	}
409	
410	/** The calendar date (YYYY-MM-DD) of a number of days since 1970-01-01. */
411	function fromDayNumber(n: number): string {
412	  const z = n + 719468;
413	  const era = Math.floor(z / 146097);
414	  const doe = z - era * 146097;
415	  const yoe = Math.floor((doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365);
416	  const doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100));
417	  const mp = Math.floor((5 * doy + 2) / 153);
418	  const d = doy - Math.floor((153 * mp + 2) / 5) + 1;
419	  const m = mp < 10 ? mp + 3 : mp - 9;
420	  const y = yoe + era * 400 + (m <= 2 ? 1 : 0);
421	  return `${String(y).padStart(4, '0')}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
422	}
