424	/** A real calendar date written YYYY-MM-DD. */
425	export function isDate(s: string): boolean {
426	  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s);
427	  if (!m) return false;
428	  const [y, mo, d] = [Number(m[1]), Number(m[2]), Number(m[3])];
429	  const leap = (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
430	  const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
431	  return mo >= 1 && mo <= 12 && d >= 1 && d <= days[mo - 1];
432	}
